using System.Linq;using UnityEngine;using UnityEditor;using LWS.TruckSports.Editor;
namespace LWS.TruckMinefield.Editor {public static class MinefieldEffectsAuthoring {
 public static void Install(MinefieldMatch m){var old=GameObject.Find("Bounded Minefield flight and landing effects");if(old!=null)Object.DestroyImmediate(old);var root=new GameObject("Bounded Minefield flight and landing effects").transform;var material=SportsChaosAuthoring.Flare(MinefieldAuthoring.Folder);m.flightTrails=new TrailRenderer[8];for(int i=0;i<8;i++){var g=new GameObject("Colored airborne trace "+i);g.transform.SetParent(root,false);var trail=g.AddComponent<TrailRenderer>();trail.sharedMaterial=material;trail.time=.65f;trail.startWidth=.18f;trail.endWidth=0;trail.minVertexDistance=.18f;trail.alignment=LineAlignment.View;trail.emitting=false;trail.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;trail.receiveShadows=false;m.flightTrails[i]=trail;}m.landPuffs=new ParticleSystem[4];for(int i=0;i<4;i++){var puff=new GameObject("Pooled terrain contact puff "+i).AddComponent<ParticleSystem>();puff.transform.SetParent(root,false);SportsChaosAuthoring.FixBlast(puff,material);var main=puff.main;main.startColor=new ParticleSystem.MinMaxGradient(new Color(.55f,.37f,.18f,.5f),new Color(.3f,.23f,.12f,.35f));main.startSpeed=new ParticleSystem.MinMaxCurve(1,3);main.startSize=new ParticleSystem.MinMaxCurve(.2f,.8f);main.startLifetime=new ParticleSystem.MinMaxCurve(.3f,.7f);m.landPuffs[i]=puff;}MinefieldGoddessAuthoring.Flags(m);
 if(m.feedback.clips.Length<8)m.feedback.clips=m.feedback.clips.Concat(new[]{AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckDockDiving/Audio/Ordinary applause.wav")}).ToArray();EditorUtility.SetDirty(m);}
}}
